export function PowerSearchValueEditor({
  operatorValue,
  filterValue,
  onChange,
  onEnter,
  maxMenuItems,
  isDisabled,
  onUnstage,
  presentation = 'popover',
  fieldLabel,
  timezoneID,
}: PowerSearchValueEditorProps) {
  switch (operatorValue.type) {
    case 'empty':
      return null;

    case 'string':
      return (
        <StringEditor
          isDisabled={isDisabled}
          presentation={presentation}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          onEnter={onEnter}
          maxMenuItems={maxMenuItems}
        />
      );

    case 'string_list':
      return (
        <StringListEditor
          isDisabled={isDisabled}
          presentation={presentation}
          fieldLabel={fieldLabel}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          maxMenuItems={maxMenuItems}
        />
      );

    case 'integer':
      return (
        <IntegerEditor
          isDisabled={isDisabled}
          presentation={presentation}
          onUnstage={onUnstage}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          onEnter={onEnter}
        />
      );

    case 'float':
      return (
        <FloatEditor
          isDisabled={isDisabled}
          presentation={presentation}
          onUnstage={onUnstage}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          onEnter={onEnter}
        />
      );

    case 'time':
      return (
        <TimeEditor
          isDisabled={isDisabled}
          presentation={presentation}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
        />
      );

    case 'date_absolute':
      return (
        <DateAbsoluteEditor
          isDisabled={isDisabled}
          presentation={presentation}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          timezoneID={timezoneID}
        />
      );

    case 'date_relative':
      return (
        <DateRelativeEditor
          isDisabled={isDisabled}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
        />
      );

    case 'date_range':
      return (
        <DateRangeEditor
          isDisabled={isDisabled}
          presentation={presentation}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          timezoneID={timezoneID}
        />
      );

    case 'enum':
      return (
        <EnumEditor
          isDisabled={isDisabled}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
        />
      );

    case 'enum_list':
      return (
        <EnumListEditor
          isDisabled={isDisabled}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
        />
      );

    case 'entity_list':
      return (
        <EntityListEditor
          isDisabled={isDisabled}
          presentation={presentation}
          fieldLabel={fieldLabel}
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          maxMenuItems={maxMenuItems}
        />
      );

    case 'custom':
      return (
        <CustomEditor
          operatorValue={operatorValue}
          filterValue={filterValue}
          onChange={onChange}
          isDisabled={isDisabled}
        />
      );

    case 'nested':
      // Nested filters are complex — simplified v1 just shows a message
      return null;

    default:
      return null;
  }
}

