      part.matches(BLOCKS) ||
      (display !== '' &&
        display !== 'contents' &&
        !display.startsWith('inline')) ||
      /\b(flex|grid)\b/.test(parentDisplay);
    if (isBlock) {
      parts.push(' ');
    }
    part.childNodes.forEach(child => walk(child, display));
    if (isBlock) {
      parts.push(' ');
